def md(frame):
    lines=['| '+' | '.join(map(str,frame.columns))+' |','| '+' | '.join(['---']*len(frame.columns))+' |']
    for vals in frame.itertuples(index=False,name=None):lines.append('| '+' | '.join(str(v).replace('|','/') for v in vals)+' |')
    return '\n'.join(lines)

def sha(path):
    h=hashlib.sha256()
    with open(path,'rb') as f:
        for c in iter(lambda:f.read(1048576),b''):h.update(c)
    return h.hexdigest()

