    original95=st.groupby('contrast').agg(original_positive_tests=('cluster_id','size'),survive_measurement95=('valid_dominance95','sum'),BY_positive95=('BY_positive_dominance95','sum'),total_valid_thinning_tests=('n_measurement_valid','sum'),BY_positive_in_any_thinning=('n_BY_positive',lambda x:int((x>0).sum()))).reset_index();original95.to_csv(R/'original_hit_retention_by_contrast.csv',index=False)
    thinsum=thin.groupby(['replicate','contrast']).agg(n_tests=('cluster_id','size'),n_measurement_valid=('measurement_valid','sum'),min_exact_p=('exact_p','min'),min_BH_q=('BH_q_full_2769','min'),min_BY_q=('BY_q_full_2769','min'),BH_positive=('BH_q_full_2769',lambda x:int((x<=.05).sum())),BY_positive=('BY_positive','sum')).reset_index();thinsum.to_csv(R/'all_thinning_family_summaries.csv',index=False)
