    ax.axhline(.05,c='#333333',ls='--',lw=1);ax.set_yscale('log');ax.set_ylim(.02,1.15);ax.set_yticks([.02,.05,.1,.3,1],['0.02','0.05','0.1','0.3','1']);ax.set_xticks([0,1,3,5,7,9,11],['Orig','95%','2','4','6','8','10']);ax.get_xticklabels()[0].set_horizontalalignment('right');ax.get_xticklabels()[1].set_horizontalalignment('left');ax.set_xlabel('Original, 95% gate, then thinning replicate');ax.set_ylabel('Full-family BY q');ax.set_title('b) Tcaf1 local depth sensitivity',loc='left',fontweight='bold');ax.text(.02,.97,'Dashed: q=0.05\nValid in all 10 thinnings',transform=ax.transAxes,va='top',fontsize=8)
